const WALLPAPERS={cream:{name:'クリームの壁紙',cost:0,color:'#9e795b'},mint:{name:'ミントの壁紙',cost:160,color:'#83aa9a'},sky:{name:'空色の壁紙',cost:180,color:'#87a9c9'},pink:{name:'さくらの壁紙',cost:190,color:'#c99aab'}};const FLOORS={wood:{name:'木の床',cost:0,color:'#d9c5a2'},white:{name:'白い板の床',cost:170,color:'#e9dfc9'},brown:{name:'こげ茶の床',cost:170,color:'#b99b7c'},green:{name:'草色の床',cost:180,color:'#c3d2a9'}};state.wallpaper=WALLPAPERS[state.wallpaper]?state.wallpaper:'cream';state.flooring=FLOORS[state.flooring]?state.flooring:'wood';state.ownedWallpapers=Array.isArray(state.ownedWallpapers)?state.ownedWallpapers.filter(k=>WALLPAPERS[k]):[];state.ownedFloors=Array.isArray(state.ownedFloors)?state.ownedFloors.filter(k=>FLOORS[k]):[];if(!state.ownedWallpapers.includes('cream'))state.ownedWallpapers.push('cream');if(!state.ownedFloors.includes('wood'))state.ownedFloors.push('wood');
state.furnitureOwned=Array.isArray(state.furnitureOwned)?state.furnitureOwned.filter(k=>FURNITURE[k]):[];
state.furniturePlaced=Array.isArray(state.furniturePlaced)?state.furniturePlaced.filter(f=>f&&FURNITURE[f.kind]&&Number.isInteger(f.x)&&Number.isInteger(f.y)):[];
function validFurnitureSpot(x,y,ignore=-1){if(x<2||x>17||y<2||y>9||x===10&&y>=8)return false;if(within(homeBed,x,y)||homeFurniture.some(r=>within(r,x,y)))return false;if(state.scene==='home'&&state.x===x&&state.y===y)return false;return !state.furniturePlaced.some((f,i)=>i!==ignore&&f.x===x&&f.y===y)}
let editorOpen=false,editDraft=[],editOwned=[],editSelected=null,editHistory=[];
function editSnapshot(){editHistory.push({placed:structuredClone(editDraft),owned:[...editOwned],selected:editSelected});if(editHistory.length>50)editHistory.shift()}
function openFurnitureEditor(){if(state.scene!=='home'){tell('模様替えは自宅の中でできます。');return}editorOpen=true;editDraft=structuredClone(state.furniturePlaced);editOwned=[...state.furnitureOwned];editSelected=null;editHistory=[];document.getElementById('editor').classList.add('open');drawEditor()}
function editValid(x,y,ignore=-1){if(x<2||x>17||y<2||y>9||x===10&&y>=8)return false;if(within(homeBed,x,y)||homeFurniture.some(r=>within(r,x,y)))return false;if(x===state.x&&y===state.y)return false;return !editDraft.some((f,i)=>i!==ignore&&f.x===x&&f.y===y)}
function drawEditor(){const tools=document.getElementById('editTools'),grid=document.getElementById('editGrid'),status=document.getElementById('editStatus');tools.replaceChildren();grid.replaceChildren();const help=document.createElement('span');help.textContent='配置する家具：';tools.append(help);editOwned.forEach((kind,i)=>{const b=document.createElement('button');b.textContent=FURNITURE[kind].name+'（持ち物）';b.className=editSelected?.type==='owned'&&editSelected.i===i?'active':'';b.onclick=()=>{editSelected={type:'owned',i};drawEditor()};tools.append(b)});if(!editOwned.length){const b=document.createElement('span');b.textContent='持ち物の家具はありません';tools.append(b)}for(let y=0;y<H;y++)for(let x=0;x<W;x++){const b=document.createElement('button');const fi=editDraft.findIndex(f=>f.x===x&&f.y===y);const fixed=within(homeBed,x,y)||homeFurniture.some(r=>within(r,x,y));const blocked=x<2||x>17||y<2||y>9||x===10&&y>=8||x===state.x&&y===state.y;b.className=fi>=0?'used':fixed?'fixed':blocked?'wall':'';if(editSelected?.type==='placed'&&editSelected.i===fi&&fi>=0)b.className+=' selected';b.textContent=fi>=0?({chair:'椅',plant:'植',rug:'敷',lamp:'灯',table:'机',bookshelf:'本',cushion:'座',clock:'時'}[editDraft[fi].kind]||'家'):fixed?'■':x===state.x&&y===state.y?'人':'';b.setAttribute('aria-label',(x+1)+'列'+(y+1)+'行 '+(fi>=0?FURNITURE[editDraft[fi].kind].name:fixed?'固定家具':'空きマス'));b.onclick=()=>{if(fi>=0){editSelected={type:'placed',i:fi};status.textContent=FURNITURE[editDraft[fi].kind].name+'を選択中。移動先の空きマスを押すか「片付け」を押してください。';drawEditor();return}if(!editSelected){status.textContent='先に持ち物か配置済みの家具を選んでください。';return}const ignore=editSelected.type==='placed'?editSelected.i:-1;if(!editValid(x,y,ignore)){status.textContent='そこには置けません。通路や家具を避けてください。';return}editSnapshot();if(editSelected.type==='owned'){const kind=editOwned.splice(editSelected.i,1)[0];editDraft.push({kind,x,y})}else{editDraft[editSelected.i].x=x;editDraft[editSelected.i].y=y}editSelected=null;status.textContent='家具を配置しました。保存するまで自由に変更できます。';drawEditor()};grid.append(b)}if(editSelected?.type==='placed'){const b=document.createElement('button');b.textContent='選択した家具を片付ける';b.onclick=()=>{editSnapshot();const f=editDraft.splice(editSelected.i,1)[0];editOwned.push(f.kind);editSelected=null;status.textContent='家具を持ち物に戻しました。';drawEditor()};tools.append(b)}}
function closeFurnitureEditor(commit){if(commit){state.furniturePlaced=editDraft;state.furnitureOwned=editOwned;save(false);tell('模様替えを保存しました。')}else tell('模様替えの変更を取り消しました。');editorOpen=false;document.getElementById('editor').classList.remove('open');renderChoices([])}
document.getElementById('editDone').onclick=()=>closeFurnitureEditor(true);document.getElementById('editCancel').onclick=()=>closeFurnitureEditor(false);document.getElementById('editUndo').onclick=()=>{const p=editHistory.pop();if(!p){document.getElementById('editStatus').textContent='これ以上戻せません。';return}editDraft=p.placed;editOwned=p.owned;editSelected=null;drawEditor()};

// Phase 6.1: 家具収集・部屋評価。購入済み履歴は旧セーブで不明なため、現存家具から補完。
state.furnitureCatalog=Array.isArray(state.furnitureCatalog)?state.furnitureCatalog.filter(k=>FURNITURE[k]):[];
for(const kind of [...state.furnitureOwned,...state.furniturePlaced.map(f=>f.kind)])if(!state.furnitureCatalog.includes(kind))state.furnitureCatalog.push(kind);
state.roomRewards=state.roomRewards&&typeof state.roomRewards==='object'?state.roomRewards:{};
const ROOM_MILESTONES=[{score:30,coins:100,name:'すてきなおへや'},{score:60,coins:200,name:'こだわりのおへや'},{score:90,coins:350,name:'あこがれのおへや'}];
function roomScore(){
 const placed=state.furniturePlaced;
 const types=new Set(placed.map(f=>f.kind));
 const decor=(state.wallpaper!=='cream'?8:0)+(state.flooring!=='wood'?8:0);
 const pairs=[['chair','table'],['rug','cushion'],['bookshelf','lamp'],['plant','clock']];
 const coordinated=pairs.reduce((n,[a,b])=>n+(types.has(a)&&types.has(b)?8:0),0);
 return Math.min(100,placed.length*5+types.size*4+decor+coordinated);
}
function roomRank(score){return score>=90?'あこがれのおへや':score>=60?'こだわりのおへや':score>=30?'すてきなおへや':'これからのおへや'}
function roomRatingView(){
 const score=roomScore(),types=new Set(state.furniturePlaced.map(f=>f.kind));
 const catalog=Object.entries(FURNITURE).map(([k,f])=>(state.furnitureCatalog.includes(k)?'✓ ':'□ ')+f.name).join(' ／ ');
 const ready=ROOM_MILESTONES.filter(m=>score>=m.score&&!state.roomRewards[m.score]);
 const advice=state.furniturePlaced.length<3?'家具を3つ以上置いてみよう。':types.size<4?'ちがう種類の家具を集めよう。':state.wallpaper==='cream'&&state.flooring==='wood'?'壁紙や床を変えてみよう。':'家具の組み合わせを考えてみよう。';
 tell('【おへやの評価】'+score+'点／100点　'+roomRank(score)+'。\n家具図鑑：'+state.furnitureCatalog.length+'/'+Object.keys(FURNITURE).length+'種類。\n'+catalog+'\nヒント：'+advice);
 const options=ready.map(m=>['評価'+m.score+'点のお祝い（'+m.coins+'コイン）',()=>{if(roomScore()<m.score||state.roomRewards[m.score]){roomRatingView();return}state.roomRewards[m.score]=true;state.coins+=m.coins;save(false);tell('「'+m.name+'」達成！ お祝いに'+m.coins+'コインを受け取りました。');renderChoices([['評価をもう一度見る',roomRatingView],['閉じる',()=>renderChoices([])]])}]);
 options.push(['閉じる',()=>renderChoices([])]);renderChoices(options);
}
document.getElementById('roomRating').onclick=roomRatingView;

function furnitureMenu(){renderChoices([]);tell('家具屋へようこそ。家具を買ったり、おうちに置いたりできます。');const opts=Object.entries(FURNITURE).map(([kind,f])=>[f.name+'を買う（'+f.cost+'コイン）',()=>{if(state.coins<f.cost){tell('コインが足りません。お店でお買い物のお手伝いをしよう。');return}state.coins-=f.cost;state.furnitureOwned.push(kind);if(!state.furnitureCatalog.includes(kind))state.furnitureCatalog.push(kind);tell(f.name+'を買いました！ 自宅で「家具屋・模様替え」を開いて置こう。');save(false);renderChoices([])}]);if(state.scene==='home'){opts.push(['壁紙を選ぶ',()=>openDecorMenu('wall')],['床を選ぶ',()=>openDecorMenu('floor')]);opts.push(['部屋全体の模様替えモード',openFurnitureEditor]);state.furnitureOwned.forEach((kind,index)=>opts.push(['置く：'+FURNITURE[kind].name+'（持ち物'+(index+1)+'）',()=>placeFurniture(index)]));state.furniturePlaced.forEach((f,index)=>opts.push(['しまう：'+FURNITURE[f.kind].name+'（'+(f.x+1)+','+(f.y+1)+'）',()=>{state.furnitureOwned.push(f.kind);state.furniturePlaced.splice(index,1);tell('家具を持ち物にしまいました。');save(false);furnitureMenu()}]))}opts.push(['閉じる',()=>{renderChoices([]);tell('またいつでも家具を見に来てね。')}]);renderChoices(opts)}
function openDecorMenu(type){if(state.scene!=='home'){tell('壁紙と床は自宅で変更できます。');return}const isWall=type==='wall',items=isWall?WALLPAPERS:FLOORS,owned=isWall?state.ownedWallpapers:state.ownedFloors,field=isWall?'wallpaper':'flooring';tell((isWall?'壁紙':'床')+'を選んでください。購入したものは何度でも変更できます。');renderChoices([...Object.entries(items).map(([key,v])=>[(owned.includes(key)?'変更する：':'購入する：')+v.name+(owned.includes(key)?'':'（'+v.cost+'コイン）'),()=>{if(!owned.includes(key)){if(state.coins<v.cost){tell('コインが足りません。');return}state.coins-=v.cost;owned.push(key)}state[field]=key;save(false);tell(v.name+'に変更しました！');renderChoices([['ほかの柄を見る',()=>openDecorMenu(type)],['家具屋へ戻る',furnitureMenu]])}]),['戻る',furnitureMenu]])}
function placeFurniture(index){const kind=state.furnitureOwned[index];if(!kind)return;const opts=[];for(const [label,dx,dy] of [['上',0,-1],['下',0,1],['左',-1,0],['右',1,0]]){const x=state.x+dx,y=state.y+dy;if(validFurnitureSpot(x,y))opts.push([label+'のマスに置く',()=>{state.furniturePlaced.push({kind,x,y});state.furnitureOwned.splice(index,1);renderChoices([]);tell(FURNITURE[kind].name+'を置きました。模様替えを楽しもう！');save(false)}])}opts.push(['戻る',furnitureMenu]);tell('置きたい場所の隣に立ってください。空いている方向を選ぶと家具を置けます。');renderChoices(opts)}
const shopCustomer={x:10,y:4,w:1,h:1};
const insideDoor={x:10,y:10,w:1,h:1};
const shopExitAisle={x:10,y:9,w:1,h:1};
function within(r,x,y){return x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h}
function obstacles(scene){return scene==='shop'?[...shopShelves,shopCounter,shopCustomer]:scene==='home'?[homeBed,...homeFurniture,...state.furniturePlaced.map(f=>({x:f.x,y:f.y,w:1,h:1}))]:[]}
function passable(x,y){
 if(x<1||y<1||x>=W-1||y>=H-1)return false;
 if(state.scene==='town'){
  if(treeBlocks.has(x+','+y))return false;
  if((x>=4&&x<=8&&y>=2&&y<=4)||(x>=13&&x<=17&&y>=2&&y<=4))return false;
  if(npcs.some(n=>n.x===x&&n.y===y))return false; if(FARM_PLOTS.some(p=>p.x===x&&p.y===y))return false;
 }else if(obstacles(state.scene).some(r=>within(r,x,y)))return false;
 return true;
}
if(state.scene!=='town'&&obstacles(state.scene).some(r=>within(r,state.x,state.y))){state.x=10;state.y=9;visualX=10;visualY=9}
function move(dx,dy){facing=dx<0?'left':dx>0?'right':dy<0?'up':'down';if(editorOpen||busy||choices.children.length)return;let nx=state.x+dx,ny=state.y+dy;if(state.scene==='town'&&dy<0&&ny===4){if(nx===6){enter('shop',10,9);return}if(nx===15){enter('home',10,9);return}}if(state.scene!=='town'&&dy>0&&nx===10&&ny===10){enter('town',state.scene==='shop'?6:15,5);return}if(passable(nx,ny)){state.x=nx;state.y=ny}else if(state.scene==='town'&&((nx>=4&&nx<=8&&ny>=2&&ny<=4)||(nx>=13&&nx<=17&&ny>=2&&ny<=4)))tell('建物に入るには、正面の扉へ進んでください。')}function npcPassable(n,x,y){return x>=1&&y>=1&&x<W-1&&y<H-1&&!treeBlocks.has(x+','+y)&&!((x>=4&&x<=8&&y>=2&&y<=4)||(x>=13&&x<=17&&y>=2&&y<=4))&&!(x===state.x&&y===state.y)&&!npcs.some(o=>o!==n&&o.x===x&&o.y===y)&&!FARM_PLOTS.some(p=>p.x===x&&p.y===y)}
function npcStep(){
 if(state.scene!=='town'||choices.children.length)return;
 const now=performance.now(),phase=timePhase();
 if(npcConversation&&now>=npcConversationUntil)npcConversation=null;
 if(npcConversation)return;
 for(const n of npcs){
  if(now<n.waitUntil)continue;
  const [cx,cy,r]=npcSchedules[n.name][phase];
  if(!n.destination||n.destination.phase!==phase||(n.x===n.destination.x&&n.y===n.destination.y)){
   if(Math.random()<.34){n.waitUntil=now+1600+Math.random()*3000;continue}
   let options=[];
   for(let y=Math.max(1,cy-r);y<=Math.min(H-2,cy+r);y++)for(let x=Math.max(1,cx-r);x<=Math.min(W-2,cx+r);x++){
    if(Math.abs(x-cx)+Math.abs(y-cy)<=r&&npcPassable(n,x,y))options.push([x,y]);
   }
   if(!options.length)continue;
   const [tx,ty]=options[Math.floor(Math.random()*options.length)];n.destination={x:tx,y:ty,phase};
  }
  const target=n.destination;
  const queue=[[n.x,n.y]],seen=new Set([n.x+','+n.y]),prev=new Map();let found=false;
  for(let qi=0;qi<queue.length&&!found;qi++){
   const [x,y]=queue[qi];if(x===target.x&&y===target.y){found=true;break}
   for(const [dx,dy] of [[0,1],[1,0],[0,-1],[-1,0]]){
    const nx=x+dx,ny=y+dy,k=nx+','+ny;
    if(!seen.has(k)&&npcPassable(n,nx,ny)){seen.add(k);prev.set(k,[x,y]);queue.push([nx,ny])}
   }
  }
  if(!found){n.destination=null;n.waitUntil=now+900;continue}
  let next=[target.x,target.y];while(true){const p=prev.get(next[0]+','+next[1]);if(!p)break;if(p[0]===n.x&&p[1]===n.y)break;next=p}
  const dx=next[0]-n.x,dy=next[1]-n.y;
  if(dx||dy){n.face=dx>0?'right':dx<0?'left':dy>0?'down':'up';n.x=next[0];n.y=next[1]}
  if(n.x===target.x&&n.y===target.y)n.waitUntil=now+1100+Math.random()*2300;
 }
 // 住民が隣り合うと、ときどき短い立ち話をする。
 if(Math.random()<.10){
  for(let i=0;i<npcs.length;i++)for(let j=i+1;j<npcs.length;j++){
   const a=npcs[i],b=npcs[j];if(Math.abs(a.x-b.x)+Math.abs(a.y-b.y)!==1)continue;
   const line=a.name==='ミミ'||b.name==='ミミ'?'きょうのお花、きれいだね。':'きょうもいい日だね。';
   npcConversation={a:a.name,b:b.name,line};npcConversationUntil=now+2800;
   a.waitUntil=npcConversationUntil;b.waitUntil=npcConversationUntil;
   a.face=b.x>a.x?'right':b.x<a.x?'left':b.y>a.y?'down':'up';
   b.face=a.x>b.x?'right':a.x<b.x?'left':a.y>b.y?'down':'up';return;
  }
 }
}
function tile(x,y,color){ctx.fillStyle=color;ctx.fillRect(x*T,y*T,T,T)}function label(s,x,y,color='#fff'){ctx.font='bold 13px KotobaSans,sans-serif';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#3d493c';ctx.strokeText(s,x,y);ctx.fillStyle=color;ctx.fillText(s,x,y)}// 16px pixel sprites, drawn at 2x with nearest-neighbor scaling.
const spriteCache=new Map();
function sprite(kind,color,ears,dir,frame){
 const key=[kind,color,ears,dir,frame].join('|');if(spriteCache.has(key))return spriteCache.get(key);
 const sc=document.createElement('canvas');sc.width=16;sc.height=24;const g=sc.getContext('2d');g.imageSmoothingEnabled=false;
 const rect=(x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h)};
 const dark='#4a3a35',skin='#f5d8ac';
 rect(4,20+(frame?1:0),3,3,dark);rect(9,20+(frame?0:1),3,3,dark);
 rect(3,11,10,10,color);rect(2,13,2,6,color);rect(12,13,2,6,color);
 if(kind==='human'){
  rect(4,4,8,9,skin);rect(3,3,10,4,'#4e3b30');rect(3,5,2,5,'#4e3b30');
  if(dir!=='up'){rect(5,9,2,2,dark);rect(10,9,2,2,dark)}
  rect(5,15,6,2,'#e3e7ef');
 }else{
  rect(3,4,10,10,color);
  if(ears){rect(3,0,3,8,color);rect(10,0,3,8,color);rect(4,1,1,5,'#e7b5c5');rect(11,1,1,5,'#e7b5c5')}
  else{rect(2,3,4,5,color);rect(10,3,4,5,color);rect(4,1,8,4,color)}
  if(dir!=='up'){rect(5,9,2,2,dark);rect(10,9,2,2,dark);rect(7,12,2,1,'#f5b8aa')}
  rect(6,16,4,2,'#e9d6ae');
 }
 if(dir==='left')rect(2,15,2,4,'#e5cfaa');if(dir==='right')rect(12,15,2,4,'#e5cfaa');
 spriteCache.set(key,sc);return sc;
}
function character(x,y,color,ears=false,kind='human',phase=0,dir='down'){
 const px=Math.round(x*T),py=Math.round(y*T),frame=Math.floor(Math.abs(phase))%2;
 ctx.fillStyle='#344b3655';ctx.fillRect(px+8,py+28,18,4);
 const sp=sprite(kind,color,ears,dir,frame);ctx.imageSmoothingEnabled=false;
 ctx.drawImage(sp,px,py-16,32,48);
}
function decorTile(x,y){const px=x*T,py=y*T;const n=(x*19+y*37+x*y*3)%23;
 if(state.scene!=='town'){ctx.fillStyle='#bda480';ctx.fillRect(px,py+30,32,2);ctx.fillStyle='#e6d5b4';ctx.fillRect(px+30,py,2,32);return}
 if(n<4){ctx.fillStyle='#6fae67';ctx.fillRect(px+6,py+19,3,8);ctx.fillRect(px+17,py+10,3,9);ctx.fillStyle=n%2?'#f6e0a5':'#f5b6c8';ctx.fillRect(px+5,py+17,6,5);ctx.fillRect(px+16,py+8,6,5)}
 else if(n===8){ctx.fillStyle='#6b9b58';ctx.fillRect(px+7,py+21,4,6);ctx.fillRect(px+18,py+19,4,7)}
}
function tree(x,y){const px=x*T,py=y*T;
 ctx.fillStyle='#5b422e';ctx.fillRect(px+12,py+8,9,25);
 ctx.fillStyle='#376d4d';ctx.fillRect(px+1,py+1,30,18);ctx.fillRect(px+5,py-9,23,26);
 ctx.fillStyle='#55955d';ctx.fillRect(px+4,py-6,22,16);ctx.fillRect(px+2,py+5,26,8);
 ctx.fillStyle='#79b46d';ctx.fillRect(px+7,py-7,12,5);ctx.fillRect(px+3,py+2,9,5);
 ctx.fillStyle='#2e6448';ctx.fillRect(px+20,py+11,7,5);
}

// Phase 6: day-based gardening; saves under existing save object.
const FARM_CROPS={carrot:{name:'にんじん',seed:25,days:2,sell:65},tomato:{name:'トマト',seed:40,days:3,sell:100},flower:{name:'お花',seed:20,days:2,sell:55},...Object.fromEntries(Object.entries(TOWN_DATA.crops).map(([k,v])=>[k,{name:v.name,seed:TOWN_DATA.prices[v.seed].buy,days:k==='carrot'?2:3,sell:TOWN_DATA.prices[k].shop}]))};
const FARM_PLOTS=Array.from({length:6},(_,i)=>({x:13+i%3,y:8+Math.floor(i/3)}));
state.farm=Array.isArray(state.farm)&&state.farm.length>=6&&state.farm.length<=24?state.farm:Array(6).fill(null);
state.farmBag=state.farmBag&&typeof state.farmBag==='object'?state.farmBag:{carrot:0,tomato:0,flower:0};
