function rubyText(el,text){el.replaceChildren();let last=0;const s=plainText(text);if(!L.furigana){el.textContent=s;return}for(const m of s.matchAll(readingPattern)){el.append(document.createTextNode(s.slice(last,m.index)));const ruby=document.createElement('ruby'),rt=document.createElement('rt');ruby.append(document.createTextNode(m[0]));rt.textContent=READINGS[m[0]];ruby.append(rt);el.append(ruby);last=m.index+m[0].length}el.append(document.createTextNode(s.slice(last)))}
