function countRecord(scene,domain,result,detail={}){const lvl=detail.level||level();const key=[lvl,scene,domain].join('|');const n=L.counters[key]||{answers:0,correct:0,incorrect:0,hints:0,guided:0,expressions:0};if(result==='hint')n.hints++;else if(result==='guided')n.guided++;else if(result==='expression')n.expressions++;else{n.answers++;n[result==='correct'?'correct':'incorrect']++}L.counters[key]=n;L.events.push({id:++L.seq,at:new Date().toISOString(),day:state.day,level:lvl,scene,domain,result,task:detail.task||'',answer:detail.answer||'',hinted:!!detail.hinted});L.events=L.events.slice(-500);save(false)}
function shuffleOptions(opts,seed){const arr=[...opts];let s=seed>>>0;for(let i=arr.length-1;i>0;i--){s=(Math.imul(s,1664525)+1013904223)>>>0;const j=s%(i+1);[arr[i],arr[j]]=[arr[j],arr[i]]}return arr}
