const actionBeforeLearning=action;action=function(){if(setupOpen)return;let n=null;if(state.scene==='town'&&!choices.children.length&&!editorOpen&&!mini){const [dx,dy]={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[facing];n=npcs.find(n=>n.x===state.x+dx&&n.y===state.y+dy);if(n&&storyReady(n.name))n=null}actionBeforeLearning();if(n&&choices.querySelector('button')){const b=document.createElement('button');rubyText(b,'返事をする');b.setAttribute('aria-label','返事をする');b.onclick=()=>residentLesson(n.name);choices.prepend(b)}};
// 畑：初回の手入れだけ読解を挟み、同じ日の水やりをドリルにしない。
